    <?php if ($canHistory): ?>
    <section id="history" class="organization-panel glass-tile"><div class="organization-section-heading"><div><h2>История изменений</h2><p>Неизменяемые успешно совершившиеся предметные события.</p></div></div><?php if ($history === []): ?><p class="organization-empty">События отсутствуют.</p><?php else: ?><div class="organization-history-list"><?php foreach ($history as $event): $beforeText = organization_format_history_state($event['before_state'] !== null ? (string) $event['before_state'] : null); $afterText = organization_format_history_state($event['after_state'] !== null ? (string) $event['after_state'] : null); ?><article><div><strong><?= e((string) $event['event_type']) ?></strong><span><?= e((string) $event['created_at']) ?> · <?= e((string) ($event['actor_name'] ?? 'Системная операция')) ?></span></div><?php if ($event['reason']): ?><p><?= e((string) $event['reason']) ?></p><?php endif; ?><?php if ($beforeText !== null || $afterText !== null): ?><details class="organization-history-state"><summary>Состав изменения</summary><div><?php if ($beforeText !== null): ?><section><h3>До</h3><pre><?= e($beforeText) ?></pre></section><?php endif; ?><?php if ($afterText !== null): ?><section><h3>После</h3><pre><?= e($afterText) ?></pre></section><?php endif; ?></div></details><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section>
    <?php endif; ?>
